1	//! Shared test fixtures for SMA-314 integration tests. Compiled once
2	//! per test binary via `#[path = "common/mod.rs"] mod common;` at the
3	//! top of each integration test file.
4	
5	#![allow(dead_code, clippy::type_complexity)]
6	
7	use std::collections::VecDeque;
8	use std::sync::{Arc, Mutex};
9	use std::time::Instant;
10	
11	use async_trait::async_trait;
12	use futures_core::stream::BoxStream;
13	use futures_util::stream;
14	
15	use paigasus_helikon_core::{
16	    Agent, AgentError, AgentEvent, AgentInput, CancellationToken, ContentPart,
17	    ConversationSnapshot, Item, Model, ModelCapabilities, ModelError, ModelEvent, ModelRequest,
18	    PermissionDecision, PermissionPolicy, RunContext, SequenceId, Session, SessionError,
19	    SessionEvent, TokenUsage, Tool, ToolContext, ToolError, ToolOutput,
20	};
21	
22	/// A scripted [`Model`] that emits a pre-recorded sequence of
23	/// [`ModelEvent`]s per call to [`Model::invoke`]. Pop one script per
24	/// invocation; running out of scripts yields a `ModelError`.
25	pub struct MockModel {
26	    scripts: Mutex<VecDeque<Vec<ModelEvent>>>,
27	}
28	
29	impl MockModel {
30	    pub fn with_scripts(scripts: Vec<Vec<ModelEvent>>) -> Arc<Self> {
31	        Arc::new(Self {
32	            scripts: Mutex::new(VecDeque::from(scripts)),
33	        })
34	    }
35	}
36	
37	#[async_trait]
38	impl Model for MockModel {
39	    async fn invoke(
40	        &self,
41	        _request: ModelRequest,
42	        _cancel: CancellationToken,
43	    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
44	        let script = self
45	            .scripts
46	            .lock()
47	            .unwrap()
48	            .pop_front()
49	            .ok_or_else(|| ModelError::Other(anyhow::anyhow!("no more scripted responses")))?;
50	        Ok(Box::pin(stream::iter(script.into_iter().map(Ok))))
51	    }
52	
53	    fn capabilities(&self) -> ModelCapabilities {
54	        ModelCapabilities::default()
55	    }
56	}
57	
58	/// A [`Tool`] that records every invocation and returns a static
59	/// `serde_json::Value` as its output.
60	pub struct MockTool {
61	    name: String,
62	    description: String,
63	    schema: serde_json::Value,
64	    invocations: Mutex<Vec<(serde_json::Value, Instant)>>,
65	    output: serde_json::Value,
66	}
67	
68	impl MockTool {
69	    pub fn new(name: &str, output: serde_json::Value) -> Arc<Self> {
70	        Arc::new(Self {
71	            name: name.into(),
72	            description: format!("mock tool {name}"),
73	            schema: serde_json::json!({"type": "object"}),
74	            invocations: Mutex::new(Vec::new()),
75	            output,
76	        })
77	    }
78	
79	    pub fn invocations(&self) -> Vec<(serde_json::Value, Instant)> {
80	        self.invocations.lock().unwrap().clone()
81	    }
82	}
83	
84	#[async_trait]
85	impl<Ctx> Tool<Ctx> for MockTool
86	where
87	    Ctx: Send + Sync + 'static,
88	{
89	    fn name(&self) -> &str {
90	        &self.name
91	    }
92	    fn description(&self) -> &str {
93	        &self.description
94	    }
95	    fn schema(&self) -> &serde_json::Value {
96	        &self.schema
97	    }
98	
99	    async fn invoke(
100	        &self,
101	        _ctx: &ToolContext<Ctx>,
102	        args: serde_json::Value,
103	    ) -> Result<ToolOutput, ToolError> {
104	        self.invocations
105	            .lock()
106	            .unwrap()
107	            .push((args, Instant::now()));
108	        Ok(ToolOutput::new(self.output.clone()))
109	    }
110	}
111	
112	/// A [`Tool`] that synchronizes its invocations through a
113	/// [`tokio::sync::Barrier`]. Use with `Barrier::new(N)` and N tool
114	/// instances to verify concurrent execution: if the tools run
115	/// serially, the first invocation blocks forever waiting for the
116	/// second waiter.
117	pub struct MockToolBarrier {
118	    name: String,
119	    description: String,
120	    schema: serde_json::Value,
121	    barrier: Arc<tokio::sync::Barrier>,
122	}
123	
124	impl MockToolBarrier {
125	    pub fn new(name: &str, barrier: Arc<tokio::sync::Barrier>) -> Arc<Self> {
126	        Arc::new(Self {
127	            name: name.into(),
128	            description: format!("barrier-synced mock tool {name}"),
129	            schema: serde_json::json!({"type": "object"}),
130	            barrier,
131	        })
132	    }
133	}
134	
135	#[async_trait]
136	impl<Ctx> Tool<Ctx> for MockToolBarrier
137	where
138	    Ctx: Send + Sync + 'static,
139	{
140	    fn name(&self) -> &str {
141	        &self.name
142	    }
143	    fn description(&self) -> &str {
144	        &self.description
145	    }
146	    fn schema(&self) -> &serde_json::Value {
147	        &self.schema
148	    }
149	
150	    async fn invoke(
151	        &self,
152	        _ctx: &ToolContext<Ctx>,
153	        _args: serde_json::Value,
154	    ) -> Result<ToolOutput, ToolError> {
155	        self.barrier.wait().await;
156	        Ok(ToolOutput::new(serde_json::json!({"ok": true})))
157	    }
158	}
159	
160	/// A no-op [`Session`] implementation. `append` discards;
161	/// `events` / `snapshot` return empty.
162	pub struct NoopSession;
163	
164	#[async_trait]
165	impl Session for NoopSession {
166	    async fn append(&self, _events: &[SessionEvent]) -> Result<(), SessionError> {
167	        Ok(())
168	    }
169	
170	    async fn events(&self, _since: Option<SequenceId>) -> Result<Vec<SessionEvent>, SessionError> {
171	        Ok(Vec::new())
172	    }
173	
174	    async fn snapshot(&self) -> Result<ConversationSnapshot, SessionError> {
175	        Ok(ConversationSnapshot::default())
176	    }
177	}
178	
179	/// Build a minimal [`RunContext`] suitable for integration tests.
180	pub fn noop_run_context<Ctx>() -> RunContext<Ctx>
181	where
182	    Ctx: Default + Send + Sync + 'static,
183	{
184	    RunContext::ephemeral(Ctx::default()).with_session(Arc::new(NoopSession))
185	}
186	
187	use std::sync::atomic::{AtomicUsize, Ordering};
188	
189	/// A [`Tool`] that tracks how many instances run concurrently. Each
190	/// invocation bumps `current`, records the running peak into `max`, yields
